Here’s a clean, simple **Binary Search** code in C — works for sorted arrays:  

```c
#include <stdio.h>

int binarySearch(int arr[], int n, int key) {
    int low = 0, high = n - 1, mid;

    while (low <= high) {
        mid = (low + high) / 2;

        if (arr[mid] == key)
            return mid; // found
        else if (arr[mid] < key)
            low = mid + 1; // go right
        else
            high = mid - 1; // go left
    }

    return -1; // not found
}

int main() {
    int n, key, i;
    printf("Enter number of elements: ");
    scanf("%d", &n);

    int arr[n];
    printf("Enter %d sorted elements:\n", n);
    for (i = 0; i < n; i++)
        scanf("%d", &arr[i]);

    printf("Enter element to search: ");
    scanf("%d", &key);

    int result = binarySearch(arr, n, key);

    if (result != -1)
        printf("Element found at index %d\n", result);
    else
        printf("Element not found.\n");

    return 0;
}
```

✅ **Key points:**
- Array **must be sorted** (ascending).  
- Time complexity: **O(log n)**  
- Works only for random access arrays (not linked lists).  

